#include<bits/stdc++.h>

using namespace std;

using ll = long long;

int main() {
    string s;
    ll n;
    cin >> s >> n;

    reverse(s.begin(), s.end());
    while (s.size() < 60) s.push_back('0');
    int lb = -1;
    for (int i = 0; i < 60; i++) {
        if (s[i] != '?' and s[i] - '0' != (n >> i & 1)) lb = i;
    }
    if (lb == -1) {
        cout << n << endl;
        return 0;
    }
    for (int i = lb; i < 60; i++) {
        if (s[i] == '1' or !(n >> i & 1)) continue;
        s[i] = '0';
        for (int j = 0; j < i; j++) {
            if (s[j] == '?') s[j] = '1';
        }
        for (int j = i + 1; j < 60; j++) {
            s[j] = '0' + (n >> j & 1);
        }
        ll ans = 0;
        for (int j = 59; j >= 0; j--) {
            ans *= 2;
            ans += s[j] - '0';
        }
        cout << ans << endl;
        return 0;
    }
    cout << -1 << endl;
}

